export function HoverEffect({
  style = "{{style}}",
  simulate = {{simulate}},
  duration = {{duration}},
  accent = "{{accent}}",
  label = "{{label}}",
}) {
  const active = {
    lift: { transform: "translateY(-4px)", boxShadow: "0 6px 14px rgba(36,20,48,.2)" },
    glow: { boxShadow: `0 0 0 4px ${accent}`, borderRadius: 6 },
    underline: { borderBottomColor: accent },
  }[style];
  return (
    <div style={{ width: "100%", maxWidth: 320, padding: 24, background: "#FAF7F2", border: "1px solid #24143022", borderRadius: 12, fontFamily: "system-ui, sans-serif", fontSize: 13, color: "#241430aa", textAlign: "center" }}>
      <a href="#" className="link" style={{ display: "inline-block", color: "#241430", textDecoration: "none", fontWeight: 600, padding: "8px 4px", borderBottom: "2px solid transparent", ...(simulate ? active : {}) }}>
        {label}
      </a>
      <p style={{ margin: "14px 0 0" }}>{style} effect &middot; hover the link, or toggle Simulate</p>
      <style>{`
        @media (prefers-reduced-motion: no-preference) {
          .link { transition: transform ${duration}ms ease-out, box-shadow ${duration}ms ease-out, border-color ${duration}ms ease-out; }
        }
      `}</style>
    </div>
  );
}
